impl TimeEntry {
    pub fn get_description(&self) -> String {
        match self.description.as_ref() {
            "" => constants::NO_DESCRIPTION.to_string(),
            _ => self.description.to_string(),
        }
    }

    pub fn get_duration(&self) -> Duration {
        match self.stop {
            Some(_) => Duration::seconds(self.duration),
            None => Utc::now().signed_duration_since(self.start),
        }
    }

    pub fn get_duration_hmmss(&self) -> String {
        let duration = self.get_duration();
        format!(
            "{}:{:02}:{:02}",
            duration.num_hours(),
            duration.num_minutes() % 60,
            duration.num_seconds() % 60
        )
    }

    pub fn is_running(&self) -> bool {
        self.duration.is_negative()
    }

    pub fn as_running_time_entry(&self, start: DateTime<Utc>) -> TimeEntry {
        TimeEntry {
            start,
            stop: None,
            duration: -start.timestamp(),
            created_with: Some(constants::CLIENT_NAME.to_string()),
            ..self.clone()
        }
    }

    pub fn get_display_tags(&self) -> String {
        if self.tags.is_empty() {
            "".to_string()
        } else {
            format!("[{}]", self.tags.join(", "))
        }
    }
}

impl Default for TimeEntry {
    fn default() -> Self {
        let start = Utc::now();
        Self {
            id: -1,
            created_with: Some(constants::CLIENT_NAME.to_string()),
            billable: false,
            description: "".to_string(),
            duration: -start.timestamp(),
            project: None,
            start,
            stop: None,
            tags: Vec::new(),
            task: None,
            workspace_id: -1,
        }
    }
}

impl std::fmt::Display for TimeEntry {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let local_start: DateTime<Local> = self.start.with_timezone(&Local);
        let time_str = match self.stop {
            Some(stop) => {
                let local_stop: DateTime<Local> = stop.with_timezone(&Local);
                let cross_day = local_stop.date_naive() != local_start.date_naive();
                if cross_day {
                    format!(
                        "{} ~ {}",
                        local_start.format("%Y-%m-%d %H:%M"),
                        local_stop.format("%m-%d %H:%M")
                    )
                } else {
                    format!(
                        "{}~{}",
                        local_start.format("%Y-%m-%d %H:%M"),
                        local_stop.format("%H:%M")
                    )
                }
            }
            None => format!("{}~…", local_start.format("%Y-%m-%d %H:%M")),
        };
        let summary = format!(
            //{id} {date HH:MM–HH:MM} {$/space} [{duration}]{running indicator/space} – {description}{@project} {#tags}
            "{} {} {} [{}]{} –  {}{} {}",
            self.id,
            time_str,
            if self.billable {
                "$".green().bold().to_string()
            } else {
                " ".to_string()
            },
            if self.is_running() {
                self.get_duration_hmmss().green().bold()
            } else {
                self.get_duration_hmmss().normal()
            },
            start,
            end,
            ..
        } if description.is_none()
            && billable.is_none()
            && project.is_none()
            && task.is_none()
            && tags.is_none()
            && start.is_none()
            && end.is_none() =>
        {
            return Err(Box::new(error::ArgumentError::MissingUpdateFields(
                "No fields specified to update. Use -d, -p, -t, --billable, --tags, --start, or --end to specify what to change.".to_string(),
            )));
        }
        EntryAction::Delete { id, current, .. } if id.is_none() && !current => {
            return Err(Box::new(error::ArgumentError::MissingArgument(
                "'delete' requires an entry ID or --current flag. Run `toggl entry list` to find entry IDs.".to_string(),
            )));
        }
        EntryAction::BulkEdit { json: None, .. } => {
            return Err(Box::new(error::ArgumentError::MissingArgument(
                "'bulk-edit' requires --json flag with JSON payload".to_string(),
            )));
        }
        _ => {}
    }

    let api_client = get_api_client(proxy.clone())?;

    match action {
        EntryAction::Current { json } => RunningTimeEntryCommand::execute(api_client, json).await,
        EntryAction::List {
            number,
            json,
            since,
            until,
        } => ListCommand::execute(api_client, number, json, since, until, None).await,
        EntryAction::Stop { json } => {
            StopCommand::execute(&api_client, StopCommandOrigin::CommandLine, json).await?;
            Ok(())
        }
        EntryAction::Start {
            billable,
            description,
            project,
            task,
            tags,
            start,
            end,
            json,
        } => {
            StartCommand::execute(
                api_client,
                picker,
                description,
                project,
                task,
                tags,
                billable,
                false,
                start,
                end,
                json,
            )
            .await
        }
        EntryAction::Resume { id, json } => {
            ContinueCommand::execute(api_client, None, id, json).await
        }
        EntryAction::Show { id, current, json } => {
            if current {
                // Get the current running entry and show it
                match api_client.get_current_time_entry_minimal().await? {
                    Some(entry) => ShowCommand::execute(api_client, entry.id, json).await,
                    None => Err(Box::new(error::ArgumentError::ResourceNotFound(
                        "no time entry is currently running".to_string(),
                    ))),
                }
            } else {
                // id is guaranteed Some due to validation above
                ShowCommand::execute(api_client, id.unwrap(), json).await
            }
        }
        EntryAction::Update {
            id,
            current,
            description,
            billable,
            project,
            task,
            tags,
            start,
            end,
            json,
        } => {
            if current {
                // Check if there's a running entry before attempting edit
                match api_client.get_current_time_entry_minimal().await? {
                    Some(_) => {
                        // There's a running entry, let EditCommand handle it with id=None
                        EditCommand::execute(
                            api_client,
                            None,
                            description,
                            billable,
