    DirectoryNotFound(PathBuf),
    NotADirectory(PathBuf),
    InvalidDateTime(String),
    InvalidReportDate(String),
    InvalidTimeRange(String),
    MissingUpdateFields(String),
    MultipleWorkspaces(String),
    MissingArgument(String),
    ResourceNotFound(String),
}

impl Display for ArgumentError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let summary = match self {
            ArgumentError::DirectoryNotFound(path) => {
                format!(
                    "{}: {}",
                    constants::DIRECTORY_NOT_FOUND_ERROR.red(),
                    path.display()
                )
            }
            ArgumentError::NotADirectory(path) => {
                format!(
                    "{}: {}",
                    constants::NOT_A_DIRECTORY_ERROR.red(),
                    path.display()
                )
            }
            ArgumentError::InvalidDateTime(value) => {
                format!(
                    "{}: {}\nAccepted formats: today, yesterday, now, this_week, last_week, RFC3339 (e.g. 2026-03-05T09:00:00+08:00), YYYY-MM-DD HH:MM[:SS], YYYY-MM-DDTHH:MM[:SS], YYYY-MM-DD",
                    "Invalid date/time value".red(),
                    value
                )
            }
            ArgumentError::InvalidReportDate(value) => {
                format!(
                    "{}: {}\nAccepted formats: YYYY-MM-DD (e.g. 2026-03-27), today, yesterday, now, this_week, last_week",
                    "Invalid date value".red(),
                    value
                )
            }
            ArgumentError::InvalidTimeRange(message) => {
                format!("{}: {}", "Invalid time range".red(), message)
            }
            ArgumentError::MissingUpdateFields(message) => {
                format!("{}: {}", "Missing update fields".red(), message)
            }
            ArgumentError::MultipleWorkspaces(message) => {
                format!("{}: {}", "Multiple workspaces".red(), message)
            }
            ArgumentError::MissingArgument(message) => {
                format!("{}: {}", "Missing argument".red(), message)
            }
            ArgumentError::ResourceNotFound(message) => {
                format!("{}: {}", "Resource not found".red(), message)
            }
        };
        writeln!(f, "{summary}")
    }
}

impl Error for ArgumentError {}
use crate::api;
use crate::models;
use api::client::ApiClient;
use colored::Colorize;
use models::{ResultWithDefaultError, TimeEntry};
use std::io::{self, BufWriter, Write};

pub struct StopCommand;

pub enum StopCommandOrigin {
    CommandLine,
    StartCommand,
    ContinueCommand,
}

impl StopCommand {
    pub async fn execute(
        api_client: &impl ApiClient,
        origin: StopCommandOrigin,
        json: bool,
    ) -> ResultWithDefaultError<Option<TimeEntry>> {
        match api_client.get_current_time_entry_minimal().await? {
            None => {
                match origin {
                    StopCommandOrigin::CommandLine => {
                        if json {
                            let stdout = io::stdout();
                            let mut handle = BufWriter::new(stdout);
                            writeln!(handle, r#"{{"running": false}}"#).expect("failed to print");
                        } else {
                            println!("{}", "No time entry is running at the moment".yellow());
                        }
                    }
                    StopCommandOrigin::StartCommand => (),
                    StopCommandOrigin::ContinueCommand => (),
                };

                Ok(None)
            }
            Some(running_time_entry) => {
                let stopped_time_entry = api_client
                    .stop_time_entry(running_time_entry.workspace_id, running_time_entry.id)
                    .await?;

                if json && matches!(origin, StopCommandOrigin::CommandLine) {
                    crate::commands::common::CommandUtils::print_time_entry_json(
                        &stopped_time_entry,
                    );
                } else {
                    let message = match origin {
                        StopCommandOrigin::CommandLine => "Time entry stopped successfully".green(),
                        StopCommandOrigin::StartCommand => "Running time entry stopped".yellow(),
                        StopCommandOrigin::ContinueCommand => "Running time entry stopped".yellow(),
                    };

                    println!("{}\n{}", message, stopped_time_entry.clone());
                }

                Ok(Some(stopped_time_entry))
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::api::client::MockApiClient;
    use crate::error::ApiError;
    use tokio_test::{assert_err, assert_ok};

    #[tokio::test]
    async fn stop_returns_ok_when_no_entry_is_running() {
        let mut api_client = MockApiClient::new();
        api_client
            .expect_get_current_time_entry_minimal()
            .returning(|| Ok(None));

        let result = StopCommand::execute(&api_client, StopCommandOrigin::CommandLine, false).await;
        assert_ok!(result);
    }

    #[tokio::test]
    async fn stop_returns_error_when_api_fails() {
        let mut api_client = MockApiClient::new();
        api_client
            .expect_get_current_time_entry_minimal()
            .returning(|| Err(Box::new(ApiError::Network)));

        let result = StopCommand::execute(&api_client, StopCommandOrigin::CommandLine, false).await;
        assert_err!(result);
    }
}

